package common

import("bytes";"encoding/json";"fmt";"net/http")
type ViberAdapter struct{Token string;Client *http.Client}
func(a ViberAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){sender,_:=payload["sender"].(map[string]any);message,_:=payload["message"].(map[string]any);user,_:=sender["id"].(string);if user==""{return InboundEvent{},fmt.Errorf("Viber event has no sender")};kind,_:=message["type"].(string);if kind==""{kind="text"};return InboundEvent{Platform:"viber",UserID:user,ContentType:kind,Text:fmt.Sprint(message["text"]),MediaURL:fmt.Sprint(message["media"])},nil}
func(a ViberAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{if message.Type=="audio"{return fmt.Errorf("Viber audio replies are not supported")};body:=map[string]any{"receiver":event.UserID,"type":message.Type};if message.Type=="text"{body["text"]=message.Text}else{if message.MediaURL==""{return fmt.Errorf("Viber media reply requires URL")};body["media"]=message.MediaURL;if message.Text!=""{body["text"]=message.Text}};data,_:=json.Marshal(body);req,_:=http.NewRequest(http.MethodPost,"https://chatapi.viber.com/pa/send_message",bytes.NewReader(data));req.Header.Set("X-Viber-Auth-Token",a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Viber API returned %s",resp.Status)}};return nil}
